#include "assets.hpp"
#include <fstream>
#include <cstdio>
int main(int argc,char** argv){try{assetCheck(argc==3,"Expected WBFS and output DOL path");WiiAssets disc(std::filesystem::u8path(argv[1]));auto boot=disc.read(0,0x440);uint64_t offset=uint64_t(be32(boot.data()+0x420))*4;auto header=disc.read(offset,0x100);size_t length=0x100;unsigned count=0;std::vector<std::pair<uint64_t,uint64_t>> memoryRanges,fileRanges;for(unsigned i=0;i<18;++i){uint32_t start=be32(header.data()+i*4),address=be32(header.data()+0x48+i*4),size=be32(header.data()+0x90+i*4);if(!size)continue;assetCheck(start>=0x100 && uint64_t(start)+size<=32*1024*1024,"Invalid DOL extent");assetCheck(address>=0x80000000 && uint64_t(address)+size<=0x81800000,"Invalid DOL memory range");for(auto range:memoryRanges)assetCheck(uint64_t(address)+size<=range.first || address>=range.second,"Overlapping DOL memory");for(auto range:fileRanges)assetCheck(uint64_t(start)+size<=range.first || start>=range.second,"Overlapping DOL sections");memoryRanges.push_back({address,uint64_t(address)+size});fileRanges.push_back({start,uint64_t(start)+size});length=std::max(length,size_t(start)+size);++count;std::printf("%s section %u address %08x offset %08x bytes %u\n",i<7?"text":"data",i,address,start,size);}assetCheck(count && be32(header.data()+0xe0)>=0x80000000,"Invalid DOL entry");auto bytes=disc.read(offset,length);std::ofstream output(std::filesystem::u8path(argv[2]),std::ios::binary);assetCheck(bool(output),"Cannot write DOL");output.write(reinterpret_cast<const char*>(bytes.data()),bytes.size());assetCheck(bool(output),"DOL write failed");std::printf("Verified %u DOL sections, %zu bytes; entry %08x\n",count,length,be32(header.data()+0xe0));}catch(const std::exception& error){std::fprintf(stderr,"%s\n",error.what());return 1;}}

